# Java의 signed long을 Python의 unsigned 64-bit int로 변환
def to_uint64(n):
    return n & 0xFFFFFFFFFFFFFFFF

# Java의 signed byte를 Python의 int로 변환
def to_signed_byte(b):
    return b if b < 128 else b - 256

C1_uint64 = [to_uint64(x) for x in C1]
var5_signed_byte = [to_signed_byte(b) for b in C2]

# 미로(grid) 초기화
grid = []
for i in range(64):
    row_data = []
    for j in range(64):
        # C1 배열이 벽(wall)을 정의합니다.
        if (C1_uint64[i] >> (63 - j)) & 1:
            row_data.append(1)  # Wall
        else:
            row_data.append(0)  # Path
    grid.append(row_data)

def find_shortest_path():
    """
    Finds the shortest path from (0,0) to (63,63) using BFS.
    The path length must be less than 500.
    """
    q = deque([((0, 0), [(0, 0)])])  # queue of ((pos), path)
    visited = {(0, 0)}  # set of visited positions

    while q:
        (r, c), path = q.popleft()

        # Goal reached
        if (r, c) == (63, 63):
            return path

        # Path length check
        if len(path) >= 500:
            continue

        moves = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # R, D, L, U
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 64 and 0 <= nc < 64 and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                new_path = path + [(nr, nc)]
                q.append(((nr, nc), new_path))
    return None

def solve():
    print("Miro (maze) path searching with BFS for the shortest path...")
    path = find_shortest_path()

    if not path:
        print("Path not found.")
        return

    print(f"Shortest path found! Length: {len(path)}")

    collected_bytes = []
    for r, c in path:
        index = r * 64 + c
        collected_bytes.append(var5_signed_byte[index])

    print(f"Collected {len(collected_bytes)} bytes. Padding to 500 bytes for key generation...")
    
    # The eBPF program uses a 500-byte buffer (var6) which is zero-initialized.
    # The key is derived from this buffer after the path is found.
    padded_collected_bytes = bytearray(500)
    for i in range(len(collected_bytes)):
        # Make sure bytes are in 0-255 range for bytearray
        padded_collected_bytes[i] = collected_bytes[i] & 0xFF

    key = hashlib.sha512(padded_collected_bytes).digest()

    print("Reading encrypted flag...")
    with open('ctf/2025/gpn-ctf-2025/rev/honeypot/flag', 'rb') as f:
        encrypted_flag = f.read()

    print("Decrypting flag...")
    decrypted_flag = bytearray()
    for i in range(len(encrypted_flag)):
        decrypted_flag.append(encrypted_flag[i] ^ key[i])

    print("\n" + "="*20)
    print("DECRYPTED FLAG:")
    print(decrypted_flag.decode())
    print("="*20)

if __name__ == "__main__":
    solve()
